import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        int[] counts = new int[10];
        do {
            int d = (int)(n % 10);
            counts[d]++;
            n = n / 10;
        } while(n > 0);
        for(int d = 0; d <= 9; d++) {
            if(counts[d] > 0) {
                System.out.println("Digit " + d + ": " + counts[d]);
            }
        }
    }
}

